  background: var(--primary-color);
  color: var(--primary-color-contrast);

  &:has(a) {
    cursor: pointer;

    &:hover {
      background: var(--secondary-color);
    }

    a {
      color: inherit;
    }
  }
}

/* END Custom Side Nav */

/* START Image with box shadow */
#page .pb-main .pb-image.image-with-box-shadow img {
  box-shadow: rgba(0, 0, 0, 0.2) 0 1px 4px;
  background-color: #FFF;
  border: 4px solid #FFF;
  border-radius: 4px;
}

/* END Image with box shadow */

/* START Custom Panel */
#page .pb-main .single-column-row.custom-panel {
  border-radius: 6px !important;
  border: 1px solid var(--secondary-color);
}

/* END Custom Panel */

/* Only apply these styles if a .triple-column-row exists 
containing a .pb-navigation in its first column */
:root:has(.triple-column-row > .column:first-child .pb-navigation) {

    .pb-layout-container.row-level-1>.layout-node-container.single-column-row {
        width: calc(90% - 20px) !important;
    }

    .layout-node-container.triple-column-row,
    .layout-node-container.single-column-row {
        --root-level-width: calc(90% - 20px) !important;
    }

    .pb-separator {
        --root-elements-width: calc(90% - 20px) !important;
    }

    .pb-layout-container.row-level-1 .layout-node-container.triple-column-row>.column.triple-column {
        flex: 0 0 calc(25% - 15px) !important;
        width: calc(25% - 15px) !important;
    }

    /* Middle column */
    .pb-layout-container.row-level-1 .layout-node-container.triple-column-row>.column.triple-column:nth-child(2) {
        flex: 0 0 calc(50% - 10px) !important;
        width: calc(50% - 10px) !important;
    }

    @media only screen and (max-width: 1200px) {
        .pb-layout-container.row-level-1 .layout-node-container.triple-column-row {
            flex-wrap: wrap !important;
        }

        .pb-layout-container.row-level-1 .layout-node-container.triple-column-row>.column.triple-column,
        .pb-layout-container.row-level-1 .layout-node-container.triple-column-row>.column.triple-column:nth-child(2) {
            flex: 0 0 100% !important;
            width: 100% !important;
        }
    }
