document.addEventListener("appLoaded", () => {
    const buttonSelector =
    "#app .event-cal .event-filters .title > button.arrow";

    const clickEventFilterButton = () => {
        const button = document.querySelector(buttonSelector);

        if (!button) return false;

        button.click();
        console.log("Event calendar filter button clicked.");

        return true;
    };

    // Try immediately in case the button is already loaded.
    if (clickEventFilterButton()) return;

    // Otherwise, wait for the calendar to render.
    const observer = new MutationObserver(() => {
        if (clickEventFilterButton()) {
            observer.disconnect();
        }
    });

    observer.observe(document.body, {
        childList: true,
        subtree: true
    });
});

